using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;

public class JavaAnnotation {
 public string Name;public Dictionary<string,string> Args=new Dictionary<string,string>();
 public string Get(string key,string fallback=""){string s;return Args.TryGetValue(key,out s)?s:fallback;}
}
public class JavaMember {public string Name,Type;public List<JavaAnnotation> Annotations=new List<JavaAnnotation>();public List<JavaMember> Parameters=new List<JavaMember>();public bool Method;}
public class JavaType {public string Name,Package,File,Parent="";public bool Enum;public List<string> Imports=new List<string>();public List<string> Generics=new List<string>();public List<JavaAnnotation> Annotations=new List<JavaAnnotation>();public List<JavaMember> Members=new List<JavaMember>();}
public class ApiEntry {
 public bool Selected{get;set;} public string Method{get;set;} public string Path{get;set;} public string Title{get;set;} public string Category{get;set;} public string Warning{get;set;} public string Result{get;set;}
 public Dictionary<string,object> Payload=new Dictionary<string,object>(); public string Key{get{return Method+" "+Path;}} public string Source;
}
public class JavaScanner {
 public static JavaScriptSerializer Serializer(){return new JavaScriptSerializer{MaxJsonLength=16000000,RecursionLimit=150};}
 readonly Dictionary<string,List<string>> files=new Dictionary<string,List<string>>(StringComparer.Ordinal);readonly Dictionary<string,JavaType> types=new Dictionary<string,JavaType>();readonly HashSet<string> loaded=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
 public static List<string> Lex(string text){var result=new List<string>();for(int i=0;i<text.Length;){char c=text[i];if(char.IsWhiteSpace(c)){i++;continue;}if(c=='/'&&i+1<text.Length&&text[i+1]=='/'){while(i<text.Length&&text[i]!='\n')i++;continue;}if(c=='/'&&i+1<text.Length&&text[i+1]=='*'){i+=2;while(i+1<text.Length&&!(text[i]=='*'&&text[i+1]=='/'))i++;i=Math.Min(text.Length,i+2);continue;}int start=i++;if(c=='"'||c=='\''){while(i<text.Length){char next=text[i++];if(next=='\\'&&i<text.Length){i++;continue;}if(next==c)break;}}else if(char.IsLetterOrDigit(c)||c=='_'||c=='$'){while(i<text.Length&&(char.IsLetterOrDigit(text[i])||text[i]=='_'||text[i]=='$'))i++;}result.Add(text.Substring(start,i-start));}return result;}
 static string Join(List<string> t,int start,int end){return string.Concat(t.Skip(start).Take(end-start));}
 static string Unquote(string s){if(s.StartsWith("\"")){try{return Serializer().Deserialize<string>(s);}catch{return s.Trim('"');}}return s;}
 static int Match(List<string> t,int start,string open,string close){int depth=0;for(int i=start;i<t.Count;i++){if(t[i]==open)depth++;else if(t[i]==close&&--depth==0)return i;}throw new FormatException("Java 括号未闭合");}
 static JavaAnnotation Annotation(List<string> t,ref int p){p++;var a=new JavaAnnotation{Name=t[p++]};while(p+1<t.Count&&t[p]=="."){p++;a.Name=t[p++];}if(p<t.Count&&t[p]=="("){int end=Match(t,p,"(",")");int s=++p,depth=0;for(int i=p;i<=end;i++){if(i<end&&(t[i]=="("||t[i]=="{"||t[i]=="["))depth++;if(i<end&&(t[i]==")"||t[i]=="}"||t[i]=="]"))depth--;if(i==end||(t[i]==","&&depth==0)){int eq=t.FindIndex(s,i-s,x=>x=="=");string key=eq<0?"value":Join(t,s,eq);string value=Join(t,eq<0?s:eq+1,i);a.Args[key]=Unquote(value);s=i+1;}}p=end+1;}return a;}
 static bool Modifier(string s){return new[]{"public","private","protected","static","final","abstract","synchronized","native","transient","volatile","default"}.Contains(s);}
 static List<JavaMember> Params(List<string> t,int start,int end){var list=new List<JavaMember>();int d=0,s=start;for(int i=start;i<=end;i++){if(i<end&&(t[i]=="("||t[i]=="<"||t[i]=="{"||t[i]=="["))d++;if(i<end&&(t[i]==")"||t[i]==">"||t[i]=="}"||t[i]=="]"))d--;if(i==end||(t[i]==","&&d==0)){int p=s;var anns=new List<JavaAnnotation>();while(p<i&&(t[p]=="@"||Modifier(t[p]))){if(t[p]=="@")anns.Add(Annotation(t,ref p));else p++;}if(i-p>=2)list.Add(new JavaMember{Name=t[i-1],Type=Join(t,p,i-1),Annotations=anns});s=i+1;}}return list;}
 void Load(string file){if(!loaded.Add(file))return;var t=Lex(File.ReadAllText(file));string package="";var imports=new List<string>();for(int i=0;i<t.Count;i++){if(t[i]=="package"||t[i]=="import"){bool imp=t[i]=="import";int s=++i;while(i<t.Count&&t[i]!=";")i++;if(imp)imports.Add(Join(t,s,i));else package=Join(t,s,i);}}ParseTypes(t,0,t.Count,package,imports,file,"");}
 void ParseTypes(List<string> t,int start,int end,string package,List<string> imports,string file,string outer){var anns=new List<JavaAnnotation>();for(int p=start;p<end;){if(t[p]=="@"){anns.Add(Annotation(t,ref p));continue;}if(t[p]!="class"&&t[p]!="interface"&&t[p]!="enum"){if(t[p]==";")anns.Clear();p++;continue;}var type=new JavaType{Enum=t[p]=="enum",Name=(outer.Length>0?outer+".":"")+t[p+1],Package=package,File=file,Imports=imports,Annotations=anns};anns=new List<JavaAnnotation>();p+=2;if(p<end&&t[p]=="<"){int g=Match(t,p,"<",">");for(int k=p+1;k<g;k++)if(k==p+1||t[k-1]==",")type.Generics.Add(t[k]);p=g+1;}if(p<end&&t[p]=="extends"){int s=++p;while(p<end&&t[p]!="{"&&t[p]!="implements")p++;type.Parent=Join(t,s,p);}while(p<end&&t[p]!="{")p++;if(p>=end)break;int close=Match(t,p,"{","}");types[package+"."+type.Name]=type;ParseMembers(type,t,p+1,close);p=close+1;}}
 void ParseMembers(JavaType type,List<string> t,int start,int end){var anns=new List<JavaAnnotation>();int p=start;bool staticMember=false;while(p<end){if(t[p]=="@"){anns.Add(Annotation(t,ref p));continue;}if(Modifier(t[p])){if(t[p]=="static")staticMember=true;p++;continue;}if(t[p]=="class"||t[p]=="interface"||t[p]=="enum"){int brace=p;while(brace<end&&t[brace]!="{")brace++;int close=Match(t,brace,"{","}");ParseTypes(t,p,close+1,type.Package,type.Imports,type.File,type.Name);p=close+1;anns.Clear();continue;}if(t[p]=="{"){p=Match(t,p,"{","}")+1;anns.Clear();continue;}int s=p,d=0;while(p<end){if(t[p]=="<")d++;if(t[p]==">")d--;if(d==0&&(t[p]=="("||t[p]==";"||t[p]=="="||t[p]=="{"))break;p++;}if(p>=end)break;if(t[p]=="("){int e=Match(t,p,"(",")");if(p-s>=1){var m=new JavaMember{Name=t[p-1],Type=Join(t,s,p-1),Method=true,Annotations=anns,Parameters=Params(t,p+1,e)};type.Members.Add(m);}p=e+1;while(p<end&&t[p]!="{"&&t[p]!=";")p++;if(p<end&&t[p]=="{")p=Match(t,p,"{","}")+1;else p++;}else{if(!staticMember&&p-s>=2)type.Members.Add(new JavaMember{Name=t[p-1],Type=Join(t,s,p-1),Annotations=anns});while(p<end&&t[p]!=";"){if(t[p]=="{")p=Match(t,p,"{","}");p++;}p++;}anns=new List<JavaAnnotation>();staticMember=false;}}
 public JavaScanner(string root){foreach(string f in Directory.EnumerateFiles(root,"*.java",SearchOption.AllDirectories)){if(f.IndexOf("\\target\\",StringComparison.OrdinalIgnoreCase)>=0||f.IndexOf("\\.git\\",StringComparison.OrdinalIgnoreCase)>=0)continue;string name=System.IO.Path.GetFileNameWithoutExtension(f);List<string> paths;if(!files.TryGetValue(name,out paths))files[name]=paths=new List<string>();paths.Add(f);}}
 JavaType Resolve(string name,JavaType context){JavaType found;var candidates=new List<string>{context.Package+"."+name,context.Package+"."+context.Name+"."+name,name};foreach(string import in context.Imports){if(import.EndsWith(".*"))candidates.Add(import.Substring(0,import.Length-1)+name);else if(import.EndsWith("."+name)||import.EndsWith("."+name.Split('.')[0]))candidates.Add(import+(name.Contains(".")?name.Substring(name.IndexOf('.')):""));}foreach(string candidate in candidates)if(types.TryGetValue(candidate,out found))return found;foreach(string simple in name.Split('.').Reverse()){List<string> paths;if(files.TryGetValue(simple,out paths))foreach(string file in paths)Load(file);}foreach(string candidate in candidates)if(types.TryGetValue(candidate,out found))return found;var unique=types.Values.Where(x=>x.Name==name||x.Name.EndsWith("."+name)).ToArray();if(unique.Length==1)return unique[0];return null;}
 public static JavaAnnotation Ann(List<JavaAnnotation> a,string name){return a.FirstOrDefault(x=>x.Name==name);}
 static Dictionary<string,object> Obj(params object[] pairs){var d=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)d[(string)pairs[i]]=pairs[i+1];return d;}
 static List<string> TypeArgs(string type){int p=type.IndexOf('<');if(p<0)return new List<string>();var t=Lex(type);return SplitGeneric(t,t.IndexOf("<")+1,t.Count-1);}
 static List<string> SplitGeneric(List<string> t,int s,int end){var args=new List<string>();int d=0;for(int i=s,k=s;i<=end;i++){if(i<end&&t[i]=="<")d++;if(i<end&&t[i]==">")d--;if(i==end||(t[i]==","&&d==0)){args.Add(Join(t,k,i));k=i+1;}}return args;}
 Dictionary<string,object> Schema(string type,JavaType context,List<string> warnings,HashSet<string> stack,Dictionary<string,string> vars=null){if(vars!=null&&vars.ContainsKey(type))type=vars[type];if(type.EndsWith("[]"))return Obj("type","array","items",Schema(type.Substring(0,type.Length-2),context,warnings,stack,vars));string name=type.Split('<')[0];var args=TypeArgs(type);if(new[]{"List","Set","Collection","Iterable","ArrayList"}.Contains(name))return Obj("type","array","items",Schema(args.Count>0?args[0]:"Object",context,warnings,stack,vars));if(new[]{"String","char","Character","Date","LocalDate","LocalDateTime","Instant","BigDecimal","MultipartFile"}.Contains(name))return Obj("type","string");if(new[]{"int","long","short","byte","Integer","Long","Short","Byte","BigInteger"}.Contains(name))return Obj("type","integer");if(new[]{"double","float","Double","Float"}.Contains(name))return Obj("type","number");if(name=="boolean"||name=="Boolean")return Obj("type","boolean");if(name=="void"||name=="Void")return Obj("type","null");if(name=="Map"||name=="HashMap"||name=="JSONObject"||name=="Object"){warnings.Add("动态类型需确认："+type);return Obj("type","object");}var model=Resolve(name,context);if(model==null){warnings.Add("未解析类型："+type);return Obj("type","object","description","待补充类型 "+type);}if(stack.Count>15||!stack.Add(model.Package+"."+model.Name)){warnings.Add("递归类型："+type);return Obj("type","object");}if(model.Enum){warnings.Add("枚举序列化需确认："+type);stack.Remove(model.Package+"."+model.Name);return Obj("type","string");}if(name=="Money"||Ann(model.Annotations,"JsonSerialize")!=null)warnings.Add("自定义序列化需确认："+type);var bindings=new Dictionary<string,string>();for(int i=0;i<model.Generics.Count;i++)bindings[model.Generics[i]]=i<args.Count?(vars!=null&&vars.ContainsKey(args[i])?vars[args[i]]:args[i]):"Object";var props=new Dictionary<string,object>();var required=new List<string>();if(model.Parent.Length>0&&model.Parent!="Serializable"){var parent=Schema(model.Parent,model,warnings,stack,bindings);if(parent.ContainsKey("properties"))foreach(var kv in (Dictionary<string,object>)parent["properties"])props[kv.Key]=kv.Value;}foreach(var f in model.Members.Where(x=>!x.Method)){if(Ann(f.Annotations,"JsonIgnore")!=null)continue;string fn=f.Name;var property=Ann(f.Annotations,"JsonProperty");if(property!=null)fn=property.Get("value",fn);var serial=Ann(f.Annotations,"JsonSerialize");var schema=serial!=null&&serial.Get("using").Contains("ToStringSerializer")?Obj("type","string"):Schema(f.Type,model,warnings,stack,bindings);var desc=Ann(f.Annotations,"ApiModelProperty");if(desc!=null)schema["description"]=desc.Get("value");if(desc!=null&&desc.Get("required")=="true"||f.Annotations.Any(x=>new[]{"NotNull","NotBlank","NotEmpty"}.Contains(x.Name)))required.Add(fn);props[fn]=schema;}foreach(var getter in model.Members.Where(x=>x.Method&&x.Parameters.Count==0&&x.Type!="void"&&((x.Name.StartsWith("get")&&x.Name.Length>3)||(x.Name.StartsWith("is")&&x.Name.Length>2)))){if(Ann(getter.Annotations,"JsonIgnore")!=null)continue;string gn=getter.Name.Substring(getter.Name.StartsWith("get")?3:2);gn=char.ToLowerInvariant(gn[0])+gn.Substring(1);if(!props.ContainsKey(gn))props[gn]=Schema(getter.Type,model,warnings,stack,bindings);}stack.Remove(model.Package+"."+model.Name);return Obj("type","object","properties",props,"required",required);}
 static string PathValue(JavaAnnotation annotation){return annotation==null?"":annotation.Get("value",annotation.Get("path"));}
 static string Combine(string a,string b){return "/"+(a.Trim('/')+"/"+b.Trim('/')).Trim('/');}
 public List<ApiEntry> Scan(string directory){var result=new List<ApiEntry>();foreach(string file in Directory.EnumerateFiles(directory,"*.java",SearchOption.AllDirectories))if(System.IO.Path.GetFileName(file).EndsWith("Controller.java"))Load(file);var controllers=types.Values.Where(x=>x.File.StartsWith(directory,StringComparison.OrdinalIgnoreCase)&&x.Annotations.Any(a=>a.Name=="RestController"||a.Name=="Controller")).ToArray();foreach(var c in controllers){string basePath=PathValue(Ann(c.Annotations,"RequestMapping"));var api=Ann(c.Annotations,"Api");string category=api==null?c.Name:api.Get("tags",api.Get("value",c.Name));foreach(var m in c.Members.Where(x=>x.Method)){var route=m.Annotations.FirstOrDefault(x=>new[]{"RequestMapping","GetMapping","PostMapping","PutMapping","DeleteMapping","PatchMapping"}.Contains(x.Name));if(route==null)continue;var warnings=new List<string>();string method=route.Name.Replace("Mapping","").ToUpperInvariant();if(method=="REQUEST"){method=route.Get("method").Replace("RequestMethod.","");if(method.Length==0){method="待确认";warnings.Add("未限定 HTTP 方法，请人工确认");}}string path=Combine(basePath,PathValue(route));if(path.Contains("{")&&!Regex.IsMatch(path,@"\{[A-Za-z_][A-Za-z0-9_]*\}"))warnings.Add("复杂路由需确认");if(path.Contains("\"")||path.Contains("+")||path.Contains("}" )&&path.Contains(","))warnings.Add("多路径或常量路由需确认");var operation=Ann(m.Annotations,"ApiOperation");var entry=new ApiEntry{Method=method,Path=path,Title=operation==null?m.Name:operation.Get("value",m.Name),Category=category.Trim('{','}','"'),Source=c.Name+"."+m.Name};var query=new List<object>();var pathParams=new List<object>();var headers=new List<object>();var form=new List<object>();string body="",bodyType="form";foreach(var param in m.Parameters){if(new[]{"HttpServletRequest","HttpServletResponse","MultipartHttpServletRequest"}.Contains(param.Type)){if(param.Type.Contains("Request"))warnings.Add("Servlet 请求参数需人工补充");continue;}var req=param.Annotations.FirstOrDefault(x=>new[]{"RequestParam","PathVariable","RequestHeader","RequestPart"}.Contains(x.Name));if(Ann(param.Annotations,"RequestBody")!=null){body=Serializer().Serialize(Schema(param.Type,c,warnings,new HashSet<string>()));bodyType="json";continue;}if(req!=null){var item=Obj("name",req.Get("value",req.Get("name",param.Name)),"required",req.Get("required","true")=="false"||req.Args.ContainsKey("defaultValue")?"0":"1","desc",param.Type,"example",req.Get("defaultValue"));if(req.Name=="PathVariable")pathParams.Add(item);else if(req.Name=="RequestHeader")headers.Add(item);else if(param.Type=="MultipartFile"||req.Name=="RequestPart"){item["type"]=param.Type=="MultipartFile"?"file":"text";form.Add(item);}else query.Add(item);continue;}var model=Resolve(param.Type,c);if(model!=null){var schema=Schema(param.Type,c,warnings,new HashSet<string>());var props=(Dictionary<string,object>)schema["properties"];var required=(List<string>)schema["required"];foreach(var f in model.Members.Where(x=>!x.Method)){object fs;if(!props.TryGetValue(f.Name,out fs))continue;var prop=(Dictionary<string,object>)fs;var item=Obj("name",f.Name,"required",required.Contains(f.Name)?"1":"0","desc",prop.ContainsKey("description")?prop["description"]:f.Type,"type",f.Type=="MultipartFile"?"file":"text");if(method=="GET")query.Add(item);else form.Add(item);}}else query.Add(Obj("name",param.Name,"required","0","desc",param.Type));}
 if(m.Type=="void"||m.Parameters.Any(x=>x.Type=="HttpServletResponse"))warnings.Add("文件流或直接响应需确认");var response=Schema(m.Type,c,warnings,new HashSet<string>());entry.Payload=Obj("title",entry.Title,"path",path,"method",method,"req_query",query,"req_params",pathParams,"req_headers",headers,"req_body_form",form,"req_body_type",bodyType,"req_body_other",body,"req_body_is_json_schema",true,"res_body_type","json","res_body",Serializer().Serialize(response),"res_body_is_json_schema",true,"status","undone","markdown",operation==null?"":operation.Get("notes"));entry.Warning=string.Join("；",warnings.Distinct().ToArray());entry.Selected=warnings.Count==0;result.Add(entry);}}return result.OrderBy(x=>x.Category).ThenBy(x=>x.Path).ToList();}
}


